-- Пояснения к каждому варианту для прежних вопросов тем 13–16.
-- Вопросы ищутся по полному тексту; заполняются только пустые option_notes, повторный запуск безопасен.

BEGIN;

UPDATE questions q SET option_notes = n.notes::jsonb
FROM (VALUES
    ('Какой атрибут даёт роли возможность подключаться к серверу?', '{"A":"Это привилегия на базу данных, а не атрибут роли.","B":"Право создавать базы данных.","C":"Роль с этим атрибутом — пользователь.","D":"Задаёт наследование привилегий по умолчанию при включении роли в другие роли."}'),
    ('Как сервер просматривает строки pg_hba.conf?', '{"A":"Поэтому частные правила располагают выше общих.","B":"Просмотр идёт сверху вниз.","C":"Используется первая подходящая строка, а не самая строгая.","D":"Порядок задаёт сам файл."}'),
    ('Подходящая строка в pg_hba.conf найдена, но аутентификация не прошла. Что дальше?', '{"A":"Следующие строки уже не проверяются.","B":"Решение принимается по первой подходящей строке.","C":"При неудачной аутентификации подключение отклоняется, а не ограничивается чтением.","D":"Решение принимается сразу."}'),
    ('Как работает метод аутентификации peer?', '{"A":"Пароль запрашивают методы scram-sha-256, md5 и password.","B":"Так работает trust.","C":"Так работает cert.","D":"Работает только для локальных подключений."}'),
    ('Какой парольный метод аутентификации рекомендуется использовать?', '{"A":"Менее надёжен, чем scram-sha-256.","B":"Передаёт пароль открытым текстом.","C":"Пароль вообще не проверяется.","D":"Самый надёжный из парольных методов."}'),
    ('Какие права должны быть у файла ~/.pgpass, чтобы PostgreSQL его использовал?', '{"A":"Файл доступен на чтение другим, его проигнорируют.","B":"Подходят права без доступа для группы и остальных, например 600 или 400.","C":"Файл доступен другим, его проигнорируют.","D":"Файл доступен всем, его проигнорируют."}'),
    ('Какая привилегия базы данных разрешает подключение к ней?', '{"A":"Выдана public по умолчанию.","B":"У баз данных нет привилегии USAGE.","C":"LOGIN — атрибут роли, а не привилегия.","D":"Право создавать временные таблицы."}'),
    ('Что разрешает привилегия USAGE на схему?', '{"A":"Это привилегия CREATE.","B":"Удалить схему может её владелец.","C":"Без неё объекты схемы не найти по имени.","D":"Это привилегия TEMPORARY на базу данных."}'),
    ('Что такое public в контексте ролей?', '{"A":"Суперпользователь определяется атрибутом SUPERUSER.","B":"Её привилегии получают все роли.","C":"Владелец — отдельное понятие.","D":"Для репликации нужен атрибут REPLICATION (или права суперпользователя)."}'),
    ('С какими правами выполняется функция, объявленная как SECURITY DEFINER?', '{"A":"Так работает SECURITY INVOKER, режим по умолчанию.","B":"Только если владелец функции — суперпользователь.","C":"Права проверяются, но для владельца.","D":"Так можно дать доступ к действиям, на которые у вызывающего нет прав."}'),
    ('Какие методы аутентификации запрашивают пароль?', '{"A":"Рекомендуемый парольный метод.","B":"Тоже запрашивает пароль, но менее надёжен.","C":"Спрашивает имя пользователя у ОС.","D":"Пускает без проверок."}'),
    ('Какие из перечисленных — привилегии для таблиц?', '{"A":"Опустошение таблицы.","B":"Чтение данных.","C":"Привилегия базы данных.","D":"Привилегия схем и последовательностей."}'),
    ('Что верно для владельца объекта?', '{"A":"Может, но право распоряжаться объектом за ним остаётся.","B":"Удаление объекта — право владельца.","C":"Владельцем может быть любая роль.","D":"Выдача и отзыв привилегий — право владельца."}'),
    ('Допишите команду выдачи привилегии:
```
GRANT SELECT ON accounts ___ reader;
```', '{"A":"FROM используется в REVOKE.","B":"Такого варианта нет.","C":"GRANT … TO роль.","D":"WITH GRANT OPTION дописывают после TO, а не вместо него."}'),
    ('Допишите строку pg_hba.conf, чтобы разрешить подключения из сети по паролю рекомендуемым методом:
```
# TYPE  DATABASE  USER  ADDRESS     METHOD
host    all       all   10.0.0.0/8  ___
```', '{"A":"Запрещает доступ.","B":"Работает только для локальных подключений.","C":"Рекомендуемый парольный метод.","D":"Пускает без пароля."}'),
    ('Допишите команду, чтобы reader автоматически получал право чтения новых таблиц writer:
```
ALTER DEFAULT PRIVILEGES FOR ROLE writer IN SCHEMA public
    GRANT SELECT ON ___ TO reader;
```', '{"A":"Такого типа объектов нет.","B":"Форма ALL TABLES IN SCHEMA есть у GRANT, а в привилегиях по умолчанию пишут TABLES.","C":"Нужно множественное число.","D":"Тип объектов во множественном числе."}'),
    ('Какое преимущество у логической резервной копии?', '{"A":"Восстановить можно только на момент копирования.","B":"Восстановление медленное: выполняются все команды.","C":"WAL в логической копии нет.","D":"Нужна только совместимость на уровне команд SQL."}'),
    ('Чем \copy в psql отличается от SQL-команды COPY?', '{"A":"Данные идут через клиента, это не быстрее.","B":"Файл читается или пишется на той машине, где он лежит.","C":"COPY поддерживает форматы text, csv и binary.","D":"Они отличаются тем, где находится файл."}'),
    ('Какой утилитой восстанавливают копию pg_dump в специальном формате с оглавлением?', '{"A":"Восстанавливает копию в виде SQL-скрипта.","B":"Делает физическую копию.","C":"Можно выбирать объекты, а копии форматов custom и directory — восстанавливать параллельно.","D":"Выгружает весь кластер."}'),
    ('Из какого шаблона нужно создавать базу для восстановления из pg_dump?', '{"A":"Чистый шаблон без изменений template1.","B":"Изменения template1 могут конфликтовать с содержимым копии.","C":"Это обычная база, а не шаблон для восстановления.","D":"Шаблон имеет значение."}'),
    ('Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', '{"A":"Роли и табличные пространства общие для кластера.","B":"WAL сохраняет физическое копирование.","C":"Файлы данных копирует pg_basebackup.","D":"Одну схему выгружает pg_dump -n."}'),
    ('Какое ограничение у физической резервной копии?', '{"A":"С архивом WAL можно восстановиться на нужный момент.","B":"Восстановление быстрое.","C":"Нужна двоичная совместимость.","D":"pg_basebackup снимает копию на работающем сервере."}'),
    ('Как pg_basebackup подключается к серверу?', '{"A":"COPY копирует данные таблиц, а не кластер.","B":"Протокол позволяет передавать файлы и поток WAL.","C":"SSH не используется.","D":"psql — клиент для выполнения запросов."}'),
    ('Почему копия pg_basebackup с WAL называется автономной?', '{"A":"Копия делается на работающем сервере.","B":"Место хранения роли не играет.","C":"Наоборот, сегменты WAL входят в копию.","D":"Для восстановления больше ничего не нужно."}'),
    ('Что происходит, если archive_command завершилась с ненулевым статусом?', '{"A":"Сегмент удаляется только после успешного копирования.","B":"Сервер продолжает работать.","C":"Попытки повторяются, пока команда не вернёт 0.","D":"Архивирование не отключается."}'),
    ('Какой сигнальный файл запускает восстановление из архива, после которого сервер работает как обычный, а не как реплика?', '{"A":"Сервер восстановится и станет обычным.","B":"Сервер останется репликой.","C":"Этот файл убран в PostgreSQL 12, параметры теперь в postgresql.conf.","D":"Файл с номером процесса работающего сервера."}'),
    ('Какие утилиты создают логическую резервную копию?', '{"A":"Логическая копия всего кластера.","B":"Получает поток WAL в архив.","C":"Делает физическую копию.","D":"Логическая копия одной базы."}'),
    ('Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', '{"A":"Архивация для pg_basebackup не нужна.","B":"replica — уровень по умолчанию.","C":"Право подключаться по протоколу репликации.","D":"Уровень logical не обязателен, достаточно replica."}'),
    ('Что нужно, чтобы восстановить сервер из базовой копии с архивом журналов и затем запустить его как обычный, а не как реплику?', '{"A":"Включает режим восстановления.","B":"Нужна для архивации, а не для восстановления.","C":"Команда получения сегментов из архива.","D":"Сервер останется репликой."}'),
    ('Допишите команду, чтобы сделать копию в специальном формате с оглавлением:
```
pg_dump ___ custom -f appdb.dump appdb
```', '{"A":"Добавляет команду создания базы (в текстовый дамп; для custom это делают ключом -C у pg_restore).","B":"Только данные, без определений объектов.","C":"Формат копии: -F custom.","D":"Задаёт имя файла."}'),
    ('Допишите команду, чтобы выгрузить только роли и табличные пространства:
```
pg_dumpall ___ > globals.sql
```', '{"A":"Только общие для кластера объекты.","B":"Определения всех объектов без данных.","C":"Только роли, без табличных пространств.","D":"Только данные."}'),
    ('Допишите команду, чтобы включить файловую архивацию журналов:
```
ALTER SYSTEM SET archive_mode = ___;
```', '{"A":"Включает архивацию после перезапуска; ещё нужна archive_command или archive_library.","B":"Такого значения нет: допустимы off, on и always.","C":"Недопустимое значение.","D":"Недопустимое значение."}'),
    ('В чём суть физической репликации?', '{"A":"Реплика всё время восстанавливается по журналу мастера.","B":"Команды SQL не передаются.","C":"Изменения строк передаёт логическая репликация.","D":"Это логическое копирование, а не репликация."}'),
    ('Какая совместимость серверов нужна для физической репликации?', '{"A":"Так для логической репликации.","B":"Нужны та же основная версия и платформа.","C":"Записи применяются механически, без понимания смысла.","D":"Имена баз здесь ни при чём, реплицируется весь кластер."}'),
    ('Что можно реплицировать физической репликацией?', '{"A":"Журнал общий для кластера, отдельную базу не выделить.","B":"Отдельную таблицу реплицирует логическая репликация.","C":"Журнал общий для кластера, отдельную схему не выделить.","D":"Журнал общий для всего кластера."}'),
    ('Какой процесс на реплике применяет полученные журнальные записи?', '{"A":"Получает журнал от walsender и пишет его на диск.","B":"Реплика всё время находится в режиме восстановления.","C":"Работает на основном сервере и отправляет журнал.","D":"Копирует сегменты в архив."}'),
    ('Какое минимальное значение wal_level нужно для физической репликации?', '{"A":"Части изменений нет в журнале.","B":"Уровень по умолчанию.","C":"Подходит, но нужен для логической репликации.","D":"Такого значения нет."}'),
    ('Что допускается на реплике в режиме горячего резерва?', '{"A":"Создание временных таблиц — это DDL, на реплике оно запрещено.","B":"Команды сопровождения изменяют данные.","C":"Управление доступом на реплике запрещено.","D":"Запросы только на чтение."}'),
    ('Что будет при hot_standby = off на реплике?', '{"A":"Запись на реплике невозможна в любом режиме.","B":"Репликация продолжается.","C":"Реплика применяет журнал, но клиенты к ней не подключаются.","D":"Синхронность настраивается на основном сервере."}'),
    ('Как работает фиксация при synchronous_commit = on и синхронной реплике?', '{"A":"Данные не пропадут даже при выходе мастера из строя.","B":"Так при synchronous_commit = off.","C":"Реплика не фиксирует транзакции мастера.","D":"Журнал не отключается."}'),
    ('Что даёт включение hot_standby_feedback?', '{"A":"Подтверждение фиксации — это синхронная репликация.","B":"Скорость передачи журнала не меняется.","C":"Каскад настраивается иначе.","D":"Пока работает соединение, очистка на мастере не удаляет версии, нужные запросам реплики."}'),
    ('Как выполняется переход на реплику при сбое мастера?', '{"A":"Встроенного автоматического переключения нет.","B":"Например, pg_ctl promote или функцией pg_promote().","C":"Такого механизма нет.","D":"Переход выполняется командой pg_ctl promote или функцией pg_promote()."}'),
    ('Что запрещено на реплике в режиме горячего резерва?', '{"A":"Параметры сеанса менять можно.","B":"Любые изменения данных запрещены.","C":"Команды сопровождения изменяют данные.","D":"Чтение разрешено."}'),
    ('Какие процессы участвуют в потоковой физической репликации?', '{"A":"К репликации не относится.","B":"Отправляет поток журнала реплике.","C":"Это процесс логической репликации.","D":"Получает поток журнала от walsender."}'),
    ('Что верно для каскадной репликации?', '{"A":"При включённом hot_standby_feedback основной сервер учитывает запросы всех реплик каскада.","B":"Чем дальше реплика от мастера, тем больше может быть отставание.","C":"Реплики получают журнал друг от друга по цепочке.","D":"Синхронной может быть только реплика, подключённая напрямую."}'),
    ('Допишите команду на реплике, чтобы основной сервер учитывал её снимки при очистке:
```
ALTER SYSTEM SET ___ = on;
```', '{"A":"Обратная связь с основным сервером.","B":"Разрешает запросы на реплике.","C":"Режим фиксации на основном сервере.","D":"Такого параметра нет."}'),
    ('Допишите команду на основном сервере, чтобы реплика с именем 16/replica стала синхронной:
```
ALTER SYSTEM SET synchronous_standby_names = ___;
```', '{"A":"Без кавычек значение не разберётся.","B":"Имя реплики другое.","C":"Имя со спецсимволом взято в двойные кавычки внутри строки.","D":"Без двойных кавычек символ / в имени не допускается."}'),
    ('Допишите команду на реплике, чтобы не откладывать применение конфликтующих записей:
```
ALTER SYSTEM SET max_standby_streaming_delay = ___;
```', '{"A":"Это значение по умолчанию.","B":"Конфликтующие запросы прерываются сразу.","C":"Недопустимое значение: параметр задаётся временем.","D":"Применение будет ждать бесконечно."}'),
    ('Какое значение wal_level нужно на публикующем сервере для логической репликации?', '{"A":"Не хватает данных для логического декодирования.","B":"Добавляет в журнал данные для логического декодирования.","C":"Только восстановление после сбоя.","D":"Старое название уровня replica."}'),
    ('Что передаётся подписчику при логической репликации?', '{"A":"Команды SQL не передаются.","B":"Физическая репликация передаёт записи WAL, а не страницы.","C":"Файлы WAL передаёт физическая репликация.","D":"Логическое декодирование превращает записи журнала в изменения строк."}'),
    ('Какая совместимость серверов нужна для логической репликации?', '{"A":"Подписчик лишь должен понимать протокол.","B":"Двоичная совместимость нужна физической репликации.","C":"Основные версии могут различаться.","D":"Операционные системы могут различаться."}'),
    ('Реплицируются ли команды DDL?', '{"A":"DDL не реплицируются.","B":"Тоже нет.","C":"Изменения схемы переносят вручную.","D":"Уровень журнала на это не влияет."}'),
    ('Что из перечисленного не реплицируется логической репликацией?', '{"A":"Реплицируется.","B":"Реплицируется.","C":"Последовательности не реплицируются.","D":"Реплицируется."}'),
    ('Как по умолчанию идентифицируется строка при репликации UPDATE и DELETE?', '{"A":"Режим идентификации по умолчанию.","B":"Только при REPLICA IDENTITY FULL.","C":"ctid — физический адрес, у подписчика он другой.","D":"У строк таблиц нет oid."}'),
    ('Что происходит при конфликте (нарушении ограничения) на подписчике?', '{"A":"Автоматически строка не пропускается.","B":"Такого правила нет.","C":"Подписка остаётся.","D":"Конфликт разрешают вручную."}'),
    ('Какой процесс на подписчике применяет полученные изменения?', '{"A":"Применяет журнал на физической реплике.","B":"Получает изменения и применяет их к таблицам.","C":"Получает поток WAL на физической реплике.","D":"Выполняет очистку."}'),
    ('Когда публикация по умолчанию передаёт изменения подписчику?', '{"A":"Изменения отправляются после декодирования записи о фиксации.","B":"Изменения передаются только после фиксации.","C":"Контрольная точка с этим не связана.","D":"Расписания нет."}'),
    ('Чем опасен неактивный слот логической репликации?', '{"A":"Таблицы не блокируются.","B":"Автоочистка работает, но горизонт удерживается.","C":"Сервер копит журнал и не может вычистить старые версии.","D":"Публикация не удаляется."}'),
    ('Что не передаётся логической репликацией?', '{"A":"Последовательности не реплицируются.","B":"Изменения схемы переносят вручную.","C":"Реплицируется.","D":"Реплицируется."}'),
    ('Чем логическая репликация отличается от физической?', '{"A":"Публикация может включать отдельные таблицы.","B":"Подписчик — обычный сервер, данные можно изменять.","C":"Нужна только совместимость протокола.","D":"Передаются изменения строк, а не страницы."}'),
    ('Какими способами можно идентифицировать строки при логической репликации UPDATE и DELETE?', '{"A":"ctid у подписчика другой.","B":"Номер транзакции строку не идентифицирует.","C":"Режим по умолчанию.","D":"REPLICA IDENTITY FULL."}'),
    ('Допишите команду создания публикации:
```
CREATE PUBLICATION pub ___ TABLE accounts;
```', '{"A":"Такого слова нет.","B":"FOR TABLE перечисляет публикуемые таблицы.","C":"Такого слова нет.","D":"WITH задаёт параметры публикации."}'),
    ('Допишите команду создания подписки:
```
CREATE SUBSCRIPTION sub
    CONNECTION ''host=srv1 dbname=appdb''
    ___ pub;
```', '{"A":"Такого слова нет.","B":"Такого слова нет.","C":"Такого слова нет.","D":"Имена публикаций, на которые подписываются."}'),
    ('Допишите команду, чтобы строки таблицы идентифицировались по всем столбцам:
```
ALTER TABLE accounts REPLICA IDENTITY ___;
```', '{"A":"Такого варианта нет.","B":"Идентификация по первичному ключу.","C":"Идентификация по всем столбцам строки.","D":"Такого варианта нет."}')
) AS n(question_text, notes)
WHERE q.question_text = n.question_text AND q.option_notes IS NULL;

UPDATE questions SET question_text = 'Из какого шаблона рекомендуется создавать базу для восстановления из pg_dump?' WHERE question_text = 'Из какого шаблона нужно создавать базу для восстановления из pg_dump?';
UPDATE questions SET question_text = 'Допишите команду, чтобы выгрузить только глобальные объекты кластера (роли, табличные пространства):
```
pg_dumpall ___ > globals.sql
```' WHERE question_text = 'Допишите команду, чтобы выгрузить только роли и табличные пространства:
```
pg_dumpall ___ > globals.sql
```';

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('13.', '14.', '15.', '16.'));
    IF n > 0 THEN
        RAISE EXCEPTION 'В темах 13–16 остались вопросы без пояснений к вариантам: %', n;
    END IF;
END
$check$;

COMMIT;
